function renderSelection(){ $('chooseGen').classList.toggle('active',mode==='generation');$('chooseType').classList.toggle('active',mode==='type');const list=mode==='generation'?Array.from({length:9},(_,i)=>i+1):typeOrder;$('selectionOptions').innerHTML=list.map(id=>`<label class="choice"><input type="checkbox" value="${id}" ${chosen.has(id)?'checked':''}><span ${mode==='type'?`class="type-swatch" style="--swatch:${typeColors[id-1]}"`:''}></span>${mode==='generation'?`${t('gen')} ${id}`:(language==='en'?typeEn:typeFr)[id-1]}</label>`).join('');$('selectionCount').textContent=`${chosen.size} ${t('selected')} · ${pool({mode,values:[...chosen]}).length} Pokémon`;$('selectAll').textContent=t(chosen.size===list.length?'deselectAll':'selectAll')}
