function matchesDex(p,matchingChains){if(p.playableForm===false)return false;const q=norm($('dexSearch').value),g=+$('genFilter').value,a=+$('typeFilter1').value,b=+$('typeFilter2').value;if(q){const nameMatches=norm(name(p)).includes(q),chainMatches=matchingChains&&matchingChains.has(p.chain);if(!nameMatches&&!chainMatches)return false}if(g&&p.gen!==g)return false;if(a&&!p.typeIds.includes(a))return false;if(b&&!p.typeIds.includes(b))return false;if($('oneType').checked&&p.typeIds[1])return false;if($('regionalFilter').checked&&!p.regionalForm)return false;if($('singleStage').checked&&all.some(x=>x.chain===p.chain&&x.species!==p.species))return false;let flags=['megaFilter','gmaxFilter','legendFilter','mythFilter'].filter(id=>$(id).checked);if(!flags.length)return true;return flags.every(id=>{let key={megaFilter:'selfMega',gmaxFilter:'selfGmax',legendFilter:'legendary',mythFilter:'mythical'}[id];if(id==='megaFilter'||id==='gmaxFilter')return $('chainFilter').checked?p[id==='megaFilter'?'mega':'gmax']:p[key];return p[key]})}
