function evoNavMarkup(p){const prev=dexNeighbor(p,-1),next=dexNeighbor(p,1);if(!prev&&!next)return '';const side=(mon,dir)=>{if(!mon)return '<span></span>';const arrow=`<span class="evo-arrow">${dir<0?'‹':'›'}</span>`;const content=dir<0?`${arrow}${img(mon)}<span class="evo-name">${safe(name(mon))}</span>`:`<span class="evo-name">${safe(name(mon))}</span>${img(mon)}${arrow}`;return `<button type="button" class="evo-nav-btn" data-evo-id="${mon.id}">${content}</button>`};return `<div class="evo-nav">${side(prev,-1)}${side(next,1)}</div>`}
function habitatField(p){const known=!!p.habitat[language];const info=known?'':`<button type="button" class="habitat-info" aria-expanded="false" aria-label="${safe(t('habitatInfoAria'))}">ⓘ</button><small class="habitat-note" hidden>${safe(t('habitatNote'))}</small>`;return `<div><small>${safe(t('habitat'))}</small>${safe(habitatText(p))}${info}</div>`}
function howToLegend(){return [['green',t('howToLegendGreen')],['yellow',t('howToLegendOrange')],['red',t('howToLegendRed')],['unspecified',t('howToLegendGrey')]].map(([cls,txt])=>`<div class="howto-legend-row"><span class="howto-swatch ${cls}"></span><span>${safe(txt)}</span></div>`).join('')+`<div class="howto-legend-row"><span class="howto-swatch arrow">▲▼</span><span>${safe(t('howToLegendArrow'))}</span></div>`}
function howToExampleTable(g,p){let ty=i=>{let x=g.typeIds[i],y=p.typeIds[i];return {status:x===y?'green':x&&p.typeIds.includes(x)?'yellow':'red'}};const head=['pokemon','type1','type2','habitat','color','stage','height','weight','origin'].map(k=>`<th>${k==='stage'?safe(t(k)).replace(' ','<br>'):safe(t(k))}</th>`).join('');const row=`<tr><td class="guess-cell name-cell ${g.id===p.id?'green':''}">${img(g)}${safe(name(g))}</td>${cell(g.types[language][0],ty(0))}${cell(g.types[language][1]||t('noType'),ty(1))}${cell(habitatText(g),habitatComparison(g,p))}${cell(g.color[language],comparison(g.color.en,p.color.en))}${cell(g.stage,comparison(g.stage,p.stage,true))}${cell(g.height+' m',comparison(g.height,p.height,true))}${cell(g.weight+' kg',comparison(g.weight,p.weight,true))}${cell(`${g.region[language]} · ${g.gen}`,originComparison(g,p))}</tr>`;return `<div class="guess-table-wrap howto-example-table"><table class="guess-table"><thead><tr>${head}</tr></thead><tbody>${row}</tbody></table></div>`}
let howToTopic='classic';
function renderHowToClassic(){const guess=all.find(x=>x.name.en==='Spheal'&&x.id===x.species),answer=all.find(x=>x.name.en==='Vaporeon'&&x.id===x.species);const example=guess&&answer?`<p>${safe(t('howToExampleAnswer'))}</p><p>${safe(t('howToExampleGuess'))}</p>${howToExampleTable(guess,answer)}<ul class="howto-list">${['howToExampleType1','howToExampleType2','howToExampleHabitat','howToExampleColor','howToExampleStage','howToExampleHeight','howToExampleWeight','howToExampleOrigin'].map(k=>`<li>${safe(t(k))}</li>`).join('')}</ul><p>${safe(t('howToExampleTransition'))}</p>${howToExampleTable(answer,answer)}`:'';return `<h2 id="howToTitleEl">${safe(t('howToTitle'))}</h2><p class="lead">${safe(t('howToIntro'))}</p><h3>${safe(t('howToLegendTitle'))}</h3><div class="howto-legend">${howToLegend()}</div><h3>${safe(t('howToPropsTitle'))}</h3><ul class="howto-list">${['howToPropType1','howToPropType2','howToPropHabitat','howToPropColor','howToPropStage','howToPropHeight','howToPropWeight','howToPropOrigin'].map(k=>`<li>${safe(t(k))}</li>`).join('')}</ul><h3>${safe(t('howToCluesTitle'))}</h3><ul class="howto-list">${['howToClueGen','howToClueGimmick','howToClueDesc'].map(k=>`<li>${safe(t(k))}</li>`).join('')}</ul><div class="howto-callout"><p class="howto-callout-intro">${safe(t('howToGreyIntro'))} <span class="howto-callout-note">${safe(t('howToGreyNote'))}</span></p><p>${safe(t('howToGreyText'))}</p></div><h3>${safe(t('howToExampleTitle'))}</h3>${example}<p class="howto-outro">${safe(t('howToExampleOutro'))}</p>`}
