function genderMarkup(p){const rate=p.genderRate;if(rate===-1||rate===undefined)return `<div class="gender-panel"><strong>${t('gender')}</strong><p>${t('genderless')}</p></div>`;const female=rate*12.5,male=100-female,fmt=n=>n.toLocaleString(language==='fr'?'fr-FR':'en-US',{maximumFractionDigits:1});const words=[female?`${fmt(female)} % ${t('female')}`:'',male?`${fmt(male)} % ${t('male')}`:''].filter(Boolean).join(' ; ');return `<div class="gender-panel"><strong>${t('gender')}</strong><p>${words}</p><div class="gender-bar" role="img" aria-label="${safe(words)}"><span class="male-bar" style="width:${male}%"></span><span class="female-bar" style="width:${female}%"></span></div></div>`}
function groupedEntries(entries){const seen=new Map();for(const entry of entries){const key=entry.text.replace(/\s+/g,' ').trim();if(!seen.has(key))seen.set(key,{text:entry.text,games:[]});seen.get(key).games.push(entry.game)}return [...seen.values()].map(item=>{let batches=[],previous=null;for(const game of item.games){const generation=gameGeneration(game);if(batches.length&&generation===previous)batches[batches.length-1].push(game);else batches.push([game]);previous=generation}return {game:batches.map(b=>b.join(' · ')).join(' / '),text:item.text}})}
