function gameGeneration(game){const clean=game.replace(/^Pokémon /,'');const group=gameFamilies.findIndex(family=>family.includes(clean));return group<0?clean:group}
function affinityGroup(list){return list.length?list.map(id=>`<span class="affinity-type"><i style="--swatch:${typeColors[id-1]}"></i>${safe((language==='en'?typeEn:typeFr)[id-1])}</span>`).join(''):''}
function typeAffinities(p){if(typeChart.length!==18)return '';let defensive={0:[],0.25:[],0.5:[],1:[],2:[],4:[]};for(let attack=1;attack<=18;attack++){let factor=p.typeIds.filter(Boolean).reduce((mult,defense)=>mult*typeChart[attack-1][defense-1],1);(defensive[factor]||defensive[1]).push(attack)}if(p.species===292){for(let id=1;id<=18;id++)if(!defensive[2].includes(id)&&!defensive[0].includes(id))defensive[0].push(id);for(const key of [0.25,0.5,1])defensive[key]=[]}let offensive={0:[],0.5:[],1:[],2:[]};for(let defense=1;defense<=18;defense++){let factor=Math.max(...p.typeIds.filter(Boolean).map(attack=>typeChart[attack-1][defense-1]));(offensive[factor]||offensive[1]).push(defense)}const block=(groups,keys)=>keys.map(k=>groups[k]?.length?`<div class="affinity-line"><b>${k===1?t('neutral'):'×'+k}</b><div>${affinityGroup(groups[k])}</div></div>`:'').join('');return `<div class="affinity-chart"><h4>${t('defense')}</h4>${block(defensive,[4,2,0.5,0.25,0])}<h4>${t('offense')}</h4>${block(offensive,p.species===292?[2]:[2,0.5,0])}<small>${t(p.species===292?'shedinjaHint':'damageHint')}</small></div>`}
function renderDetail(){const p=detail;if(!p)return;const en=language==='en',entries=groupedEntries(p.entries[language]),base=all.find(x=>x.species===p.species&&x.id===p.species)||p;const options=p.spriteOptions?.length?p.spriteOptions:[{file:String(p.id),label:{en:'',fr:''}}];detailIndex=(detailIndex+options.length)%options.length;const current=options[detailIndex],ownSprite=current.file===String(p.id)||current.file==='back/'+p.id,formLabel=ownSprite?[p.formLabel?.[language],current.label[language]].filter(Boolean).join(' · '):(current.label[language]||'');const family=p.formGroup?all.filter(x=>x.formGroup===p.formGroup).sort((a,b)=>(a.formOrder??0)-(b.formOrder??0)||a.id-b.id):[];const formChooser=family.length>1?`<div class="form-chooser"><label for="detailForm">${en?'Form':'Forme'}</label><select id="detailForm">${family.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${safe(x.formLabel?.[language]||name(x))}</option>`).join('')}</select></div>`:'';$('detailContent').innerHTML=`<div class="detail-head"><div class="sprite-viewer"><button id="prevSprite" class="sprite-arrow" type="button" ${options.length===1?'hidden':''} aria-label="${en?'Previous sprite':'Sprite précédent'}">‹</button><img id="detailSprite"${p.species===493?' class="pokemon-arceus"':''} src="${spriteOptionUrl(current)}" alt="${safe(name(p))}${formLabel?' — '+safe(formLabel):''}" onerror="this.onerror=null;this.src='${sprite(p,false)}'"><button id="nextSprite" class="sprite-arrow" type="button" ${options.length===1?'hidden':''} aria-label="${en?'Next sprite':'Sprite suivant'}">›</button></div><div><small>#${String(p.species).padStart(4,'0')} · ${t('gen')} ${p.gen}</small><h2 id="detailTitle">${safe(name(p))}</h2><span>${safe(p.region[language])}</span>${formLabel?`<div class="form-label">${safe(formLabel)}</div>`:''}</div></div>${evoNavMarkup(p)}${formChooser}<div class="detail-grid">${detailField(t('type1'),p.types[language][0])}${detailField(t('type2'),p.types[language][1]||t('noType'))}${habitatField(p)}${detailField(t('color'),p.color[language])}${detailField(t('stage'),p.stage)}${detailField(t('origin'),`${t('gen')} ${p.gen} · ${p.region[language]}`)}${detailField(t('height'),p.height+' m')}${detailField(t('weight'),p.weight+' kg')}</div>${genderMarkup(p)}<div class="cry-panel"><button id="playCry" class="theme-toggle" type="button">▶ ${t('cry')}</button><audio id="cryAudio" preload="none" src="assets/cries/${p.id}.ogg"></audio></div><button id="affinityToggle" class="theme-toggle affinity-toggle" type="button" aria-expanded="false">${t('affinities')}</button><div id="affinityContent" hidden>${typeAffinities(p)}</div><h3>${t('entries')}</h3>${entries.length?entries.map(e=>`<div class="entry"><strong>${safe(e.game)}</strong><p>${safe(e.text)}</p></div>`).join(''):`<p>${t(p.regionalForm?'regionalNoDesc':'noDesc')}</p>`}<p><a href="${en?'https://bulbapedia.bulbagarden.net/wiki/'+encodeURIComponent((p.wikiOverride?.en||base.name.en).replace(/ /g,'_'))+'_(Pok%C3%A9mon)':'https://www.pokepedia.fr/'+encodeURIComponent(p.wikiOverride?.fr||base.name.fr)}" target="_blank" rel="noopener noreferrer">${t('wiki')} ↗</a></p>`;if(family.length>1)$('detailForm').onchange=e=>{detail=all.find(x=>x.id===+e.target.value);detailIndex=0;renderDetail()};$$('#detailContent .evo-nav-btn').forEach(b=>b.onclick=()=>{detail=all.find(x=>x.id===+b.dataset.evoId);detailIndex=0;renderDetail()});$('prevSprite').onclick=()=>{detailIndex--;renderDetail()};$('nextSprite').onclick=()=>{detailIndex++;renderDetail()};$('detailSprite').onclick=()=>{detailIndex++;renderDetail()};const audio=$('cryAudio');let fallback=false;audio.onerror=()=>{if(!fallback&&p.id!==p.species){fallback=true;audio.src=`assets/cries/${p.species}.ogg`;audio.play().catch(()=>{})}else{$('playCry').disabled=true;$('playCry').textContent=t('cryMissing')}};$('playCry').onclick=()=>{audio.currentTime=0;audio.play().catch(()=>{})};$('affinityToggle').onclick=()=>{const panel=$('affinityContent');panel.hidden=!panel.hidden;$('affinityToggle').textContent=t(panel.hidden?'affinities':'hideAffinities');$('affinityToggle').setAttribute('aria-expanded',panel.hidden?'false':'true')};const habitatInfo=$('detailContent').querySelector('.habitat-info');if(habitatInfo)habitatInfo.onclick=()=>{const note=habitatInfo.nextElementSibling;note.hidden=!note.hidden;habitatInfo.setAttribute('aria-expanded',note.hidden?'false':'true')}}
function openDetail(id){detail=all.find(p=>p.id===id);detailIndex=0;$('detailOverlay').hidden=false;renderDetail();$('closeDetail').focus()}
function startGame(excludeId=null){if(game&&game.target!=null){if(game.guesses.length>0){localStorage.setItem('pokedle_prevTarget',game.target);refreshFooter()}}else{refreshFooter()}let p=pool();if(excludeId!==null&&p.length>1)p=p.filter(x=>x.id!==excludeId);if(!p.length)return;game={target:p[Math.floor(Math.random()*p.length)].id,guesses:[],won:false,descriptionIndex:Math.floor(Math.random()*100000)};activeHint=null;save();renderGame()}
function target(){return all.find(x=>x.id===game?.target)}
function comparison(value,answer,numeric=false){return {status:value===answer?'green':'red',arrow:numeric&&value!==answer?(answer>value?'▲':'▼'):''}}
function originComparison(guess,answer){if(guess.gen!==answer.gen)return comparison(guess.gen,answer.gen,true);return {status:guess.region.en===answer.region.en?'green':'orange',arrow:''}}
function cell(value,c){return `<td class="guess-cell ${c.status}">${safe(value)}${c.arrow?`<span class="cell-arrow">${c.arrow}</span>`:''}</td>`}
function habitatComparison(g,p){if(g.id===p.id)return {status:'green',arrow:''};if(!p.habitat.en)return g.habitat.en?{status:'red',arrow:''}:{status:'unspecified',arrow:''};if(!g.habitat.en)return {status:'unspecified',arrow:''};return comparison(g.habitat.en,p.habitat.en)}
function renderGame(){if(!all.length||!game)return;const candidates=pool(),p=target();if(!p)return;const showHabitat=candidates.some(x=>x.habitat.en);$('poolLabel').textContent=`${selection.mode==='generation'?t('poolGen'):t('poolType')}: ${selection.values.map(x=>selection.mode==='generation'?x:(language==='en'?typeEn:typeFr)[x-1]).join(', ')} · ${candidates.length} Pokémon`;$('guessHead').innerHTML=['pokemon','type1','type2',...(showHabitat?['habitat']:[]),'color','stage','height','weight','origin'].map(k=>`<th>${k==='stage'?safe(t(k)).replace(' ','<br>'):t(k)}</th>`).join('');$('guessBody').innerHTML=game.guesses.slice().reverse().map(id=>{let g=all.find(x=>x.id===id);if(!g)return '';let ty=(i)=>{let x=g.typeIds[i],y=p.typeIds[i];return {status:x===y?'green':x&&p.typeIds.includes(x)?'yellow':'red'}};return `<tr><td class="guess-cell name-cell ${g.id===p.id?'green':''}">${img(g)}${safe(name(g))}</td>${cell(g.types[language][0],ty(0))}${cell(g.types[language][1]||t('noType'),ty(1))}${showHabitat?cell(habitatText(g),habitatComparison(g,p)):''}${cell(g.color[language],comparison(g.color.en,p.color.en))}${cell(g.stage,comparison(g.stage,p.stage,true))}${cell(g.height+' m',comparison(g.height,p.height,true))}${cell(g.weight+' kg',comparison(g.weight,p.weight,true))}${cell(`${g.region[language]} · ${g.gen}`,originComparison(g,p))}</tr>`}).join('');$('guessSearch').disabled=game.won;$('rerollButton').hidden=game.won||game.guesses.length===0;$('winBanner').innerHTML=game.won?`<h2>${safe(t('won').replace('{name}',name(p)).replace('{n}',game.guesses.length).replace('{tries}',t(game.guesses.length===1?'try':'tries')))}</h2><p>${t(game.guesses.length===1?'oneShot':'first')}</p>`:'';renderHints();if($('guessSearch').value)renderSuggestions();renderProgressInfo()}
let pets=[],petRafId=null,petLastTs=null,petSpawnAt=0,petMode='chill';
const PET_W=44,PARADE_SPEED=13,CHILL_COUNT=5;
function petSetSprite(pet){pet.img.src=`assets/pets/${pet.shiny?'shiny/':''}${pet.slug}${pet.state==='idle'?'-idle':''}.gif`}
function petPlaySparkle(pet){if(!pets.includes(pet))return;const loops=Math.random()<0.5?1:2;if(pet.sparkEl)pet.sparkEl.remove();const spark=document.createElement('img');spark.className='pet-sparkle';spark.src='assets/pets/shiny-anim.gif?'+Date.now();pet.wrap.appendChild(spark);pet.sparkEl=spark;setTimeout(()=>{spark.remove();if(pet.sparkEl===spark)pet.sparkEl=null},1360*loops)}
function petArmShiny(pet,delay){if(!pet.shiny)return;setTimeout(()=>{petPlaySparkle(pet);if(pets.includes(pet))pet.shinyTimer=setInterval(()=>petPlaySparkle(pet),20000)},delay)}
function petSpawnParade(){const foot=$('petFooter');if(!foot)return;const[slug,hasShiny]=petMons[Math.floor(Math.random()*petMons.length)];const shiny=!!hasShiny&&Math.random()<0.01;const fromLeft=Math.random()<0.5;const dir=fromLeft?1:-1;const wrap=document.createElement('div');wrap.className='pet-wrap'+(dir===1?'':' flip');const img=document.createElement('img');img.className='pet-sprite';img.alt='';wrap.appendChild(img);foot.appendChild(wrap);const pet={wrap,img,slug,shiny,dir,x:fromLeft?-PET_W:window.innerWidth,state:'walking',sparkEl:null,shinyTimer:null};wrap.style.left=pet.x+'px';petSetSprite(pet);pets.push(pet);petArmShiny(pet,3000)}
function petNewTarget(pet){const maxX=Math.max(0,window.innerWidth-PET_W);pet.targetX=Math.random()*maxX;pet.state='walking';pet.speed=14+Math.random()*10;const facingRight=pet.targetX>=pet.x;pet.wrap.classList.toggle('flip',!facingRight);petSetSprite(pet)}
function petGoIdleChill(pet){pet.state='idle';pet.idleUntil=performance.now()+1500+Math.random()*4000;petSetSprite(pet)}
function petSpawnChill(){const foot=$('petFooter');if(!foot)return;const maxX=Math.max(0,window.innerWidth-PET_W);const[slug,hasShiny]=petMons[Math.floor(Math.random()*petMons.length)];const shiny=!!hasShiny&&Math.random()<0.01;const wrap=document.createElement('div');wrap.className='pet-wrap';const img=document.createElement('img');img.className='pet-sprite';img.alt='';wrap.appendChild(img);foot.appendChild(wrap);const pet={wrap,img,slug,shiny,x:Math.random()*maxX,state:'idle',sparkEl:null,shinyTimer:null};wrap.style.left=pet.x+'px';petSetSprite(pet);pet.idleUntil=performance.now()+Math.random()*3000;pets.push(pet);petArmShiny(pet,0)}
function petRemove(pet){if(pet.shinyTimer)clearInterval(pet.shinyTimer);if(pet.sparkEl)pet.sparkEl.remove();pet.wrap.remove();pets=pets.filter(p=>p!==pet)}
function petTick(ts){if(petLastTs===null)petLastTs=ts;const dt=Math.min((ts-petLastTs)/1000,0.1);petLastTs=ts;if(petMode==='parade'){for(const pet of pets.slice()){pet.x+=pet.dir*PARADE_SPEED*dt;pet.wrap.style.left=pet.x+'px';if((pet.dir===1&&pet.x>window.innerWidth)||(pet.dir===-1&&pet.x<-PET_W))petRemove(pet)}if(ts>=petSpawnAt){petSpawnParade();petSpawnAt=ts+3500+Math.random()*4500}}else{const maxX=Math.max(0,window.innerWidth-PET_W);for(const pet of pets){if(pet.state==='walking'){const dir=pet.targetX>pet.x?1:-1;pet.x+=dir*pet.speed*dt;if((dir===1&&pet.x>=pet.targetX)||(dir===-1&&pet.x<=pet.targetX)){pet.x=pet.targetX;petGoIdleChill(pet)}pet.x=Math.min(Math.max(pet.x,0),maxX);pet.wrap.style.left=pet.x+'px'}else if(pet.state==='idle'){if(ts>=pet.idleUntil)petNewTarget(pet)}}}petRafId=requestAnimationFrame(petTick)}
function refreshFooter(){const foot=$('petFooter');if(!foot)return;for(const pet of pets)if(pet.shinyTimer)clearInterval(pet.shinyTimer);foot.innerHTML='';pets=[];petMode=Math.random()<0.5?'parade':'chill';if(petMode==='chill'){for(let i=0;i<CHILL_COUNT;i++)petSpawnChill()}else{petSpawnAt=performance.now()}if(petRafId===null){petLastTs=null;petRafId=requestAnimationFrame(petTick)}}
function winText(wins){if(wins===64)return 'N64';if(wins===67)return '67 SIX SEVEN';if(wins===69)return '69 noice';if(wins===100)return '100 Ze hundred';if(wins===10)return language==='fr'?'10 c bcp là':'10 u still here?';return wins===1?'1 win':wins+' winz'}
function renderProgressInfo(){const wins=parseInt(localStorage.getItem('pokedle_wins'),10)||0;const prevId=parseInt(localStorage.getItem('pokedle_prevTarget'),10);const prev=isNaN(prevId)?null:all.find(x=>x.id===prevId);const winEl=$('winCountInfo'),prevEl=$('prevTargetInfo');if(wins>0){winEl.hidden=false;winEl.textContent=winText(wins)}else winEl.hidden=true;if(prev){prevEl.hidden=false;prevEl.innerHTML=`${safe(t('lastPokemon'))} ${img(prev)}${showPrevName?' '+safe(name(prev)):''}`;prevEl.style.cursor='pointer';prevEl.onclick=()=>{showPrevName=!showPrevName;renderProgressInfo()}}else prevEl.hidden=true;$('progressInfo').hidden=winEl.hidden&&prevEl.hidden}
function maskHintName(description,p){const base=all.find(x=>x.id===p.species)||p;const names=[p.name.en,p.name.fr,base.name.en,base.name.fr].filter(Boolean).sort((a,b)=>b.length-a.length);const unique=[...new Set(names)];const escape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const pattern=new RegExp('(?<![\\p{L}\\p{N}])(?:'+unique.map(escape).join('|')+')(?![\\p{L}\\p{N}])','giu');return description.replace(pattern,'[...]')}
function renderHints(){if(!game)return;let p=target(),counts={generation:6,power:10,description:15};let showPower=pool().some(x=>x.mega||x.gmax);$$('[data-hint]').forEach(btn=>{let kind=btn.dataset.hint,rem=Math.max(0,counts[kind]-game.guesses.length),ready=game.won||rem===0;btn.hidden=kind==='power'&&!showPower;btn.disabled=!ready;btn.classList.toggle('hint-ready',ready);btn.textContent=t(kind==='generation'?'hintGen':kind==='power'?'hintPower':'hintDesc')+(ready?'':` (${rem})`);btn.setAttribute('aria-pressed',activeHint===kind?'true':'false')});let msg='';if(activeHint==='generation')msg=`${t('gen')} ${p.gen} · ${p.region[language]}`;if(activeHint==='power')msg=t(p.mega?(p.gmax?'powerBoth':'powerMega'):(p.gmax?'powerGmax':'powerNone'));if(activeHint==='description'){let e=p.entries[language];msg=e.length?maskHintName(e[game.descriptionIndex%e.length].text,p):t(p.regionalForm?'regionalNoDesc':'noDesc')}$('hintMessage').textContent=msg}
function renderSuggestions(){if(!game||game.won)return;let q=norm($('guessSearch').value);filteredSuggestions=q?pool().filter(x=>!game.guesses.includes(x.id)&&norm(name(x)).includes(q)).sort((a,b)=>{let aa=norm(name(a)).startsWith(q)?0:1,bb=norm(name(b)).startsWith(q)?0:1;return aa-bb||a.species-b.species||a.id-b.id}).slice(0,30):[];suggestionIndex=0;$('suggestions').innerHTML=filteredSuggestions.map((p,i)=>`<button class="suggestion-item" type="button" role="option" aria-selected="${i===0}" data-id="${p.id}">${img(p)}<span>${safe(name(p))}</span></button>`).join('');$('guessSearch').setAttribute('aria-expanded',filteredSuggestions.length?'true':'false')}
function playGuessCry(p){if(!criesEnabled)return;if(gameCry){gameCry.pause();gameCry.currentTime=0}const audio=new Audio(`assets/cries/${p.id}.ogg`);gameCry=audio;let fallback=false;audio.onerror=()=>{if(!fallback&&p.id!==p.species){fallback=true;audio.src=`assets/cries/${p.species}.ogg`;audio.play().catch(()=>{})}};audio.play().catch(()=>{})}
function guess(id){if(!game||game.won||!pool().some(x=>x.id===id)||game.guesses.includes(id))return;playGuessCry(all.find(x=>x.id===id));game.guesses.push(id);game.won=id===game.target;if(game.won)localStorage.setItem('pokedle_wins',(parseInt(localStorage.getItem('pokedle_wins'),10)||0)+1);$('guessSearch').value='';$('suggestions').innerHTML='';activeHint=null;save();renderGame();$('guessSearch').focus()}
function updateSettings(){document.body.classList.toggle('light',light);localStorage.setItem('pokedle_light',light?'1':'0');localStorage.setItem('pokedle_lang',language);translate()}
function openConfirm(kind,commit){confirmKind=kind;$('confirmText').textContent=t(kind==='reroll'?'rerollWarning':'resetWarning');$('acceptReset').textContent=t(kind==='reroll'?'reroll':'reset');$('cancelReset').textContent=t(kind==='reroll'?'cancelReroll':'cancelSelection');$('confirmOverlay').hidden=false;$('acceptReset').onclick=()=>{commit();$('confirmOverlay').hidden=true};$('cancelReset').focus()}
function confirm(){if(!chosen.size){$('selectionError').textContent=t('none');$('selectionError').dataset.kind='none';return}let next={mode,values:[...chosen].sort((a,b)=>a-b)};if(JSON.stringify(next)===JSON.stringify(selection)){if(!game)startGame();go('classic');return}let commit=()=>{selection=next;startGame();$('confirmOverlay').hidden=true;go('classic')};if(game?.guesses?.length&&!game.won)openConfirm('selection',commit);else commit()}
function applyFavicon(){if(!all.length)return;const p=all.find(x=>x.id===(light?643:644));if(!p)return;const isShiny=Math.random()<1/50;let link=document.querySelector('link[rel="icon"]');if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}link.type='image/png';link.href=sprite(p,isShiny)}
async function init(){try{const res=await fetch('data.json');if(!res.ok)throw Error(res.status);all=await res.json();try{const chart=await fetch('type-chart.json');if(chart.ok)typeChart=await chart.json()}catch{}applyFavicon();refreshFooter();restore();if(game?.won&&page==='classic')startGame();updateSettings();go(page)}catch(e){$('selectionError').textContent='Data could not load. Start a local server (see README).'}}
$('cryToggle').onclick=()=>{criesEnabled=!criesEnabled;localStorage.setItem('pokedle_cries',criesEnabled?'1':'0');$('cryToggle').textContent=t(criesEnabled?'cryToggleOn':'cryToggleOff');$('cryToggle').setAttribute('aria-pressed',criesEnabled?'true':'false');$('cryToggle').classList.toggle('practice-active',criesEnabled);if(!criesEnabled&&gameCry){gameCry.pause();gameCry.currentTime=0}};$('rerollButton').onclick=()=>{if(!game||game.won||!game.guesses.length)return;const previous=game.target;openConfirm('reroll',()=>{startGame(previous);go('classic')})};$('navDex').onclick=()=>go('dex');$('navGame').onclick=()=>{if(lastClassicTab==='classic'){if(!game)startGame();go('classic')}else go('selection')};$('tabSelection').onclick=()=>go('selection');$('tabClassic').onclick=()=>{if(!game)startGame();go('classic')};$('langToggle').onclick=()=>{language=language==='en'?'fr':'en';updateSettings()};$('themeToggle').onclick=()=>{light=!light;applyFavicon();updateSettings()};$('chooseGen').onclick=()=>{mode='generation';chosen=drafts.generation;renderSelection();saveUI()};$('chooseType').onclick=()=>{mode='type';chosen=drafts.type;renderSelection();saveUI()};$('selectAll').onclick=()=>{const max=mode==='generation'?9:18;drafts[mode]=chosen=new Set(chosen.size===max?[]:Array.from({length:max},(_,i)=>i+1));renderSelection();saveUI()};$('selectionOptions').onchange=e=>{let n=+e.target.value;if(e.target.checked)chosen.add(n);else chosen.delete(n);$('selectionCount').textContent=`${chosen.size} ${t('selected')} · ${pool({mode,values:[...chosen]}).length} Pokémon`;$('selectionError').textContent='';delete $('selectionError').dataset.kind;$('selectAll').textContent=t(chosen.size===(mode==='generation'?9:18)?'deselectAll':'selectAll');saveUI()};$('confirmSelection').onclick=confirm;$('cancelReset').onclick=()=>{$('confirmOverlay').hidden=true};$('confirmOverlay').onclick=e=>{if(e.target===$('confirmOverlay'))$('confirmOverlay').hidden=true};$('dexSearch').oninput=()=>{renderDex();saveUI()};['genFilter','typeFilter1','typeFilter2','oneType','singleStage','megaFilter','gmaxFilter','legendFilter','mythFilter','regionalFilter','chainFilter'].forEach(id=>$(id).onchange=()=>{renderDex();saveUI()});$('shinyToggle').onclick=()=>{shiny=!shiny;$('shinyToggle').classList.toggle('practice-active',shiny);$('shinyToggle').setAttribute('aria-pressed',shiny?'true':'false');renderDex();renderGame();saveUI()};$('dexList').onclick=e=>{let b=e.target.closest('[data-id]');if(b)openDetail(+b.dataset.id)};$('closeDetail').onclick=()=>{detail=null;$('detailOverlay').hidden=true;$('cryAudio')?.pause()};$('detailOverlay').onclick=e=>{if(e.target===$('detailOverlay')){$('cryAudio')?.pause();$('detailOverlay').hidden=true;detail=null}};$('howToButton').onclick=()=>{howToTopic='classic';renderHowTo();$('howToOverlay').hidden=false;$('closeHowTo').focus()};$('dexHowToButton').onclick=()=>{howToTopic='dex';renderHowTo();$('howToOverlay').hidden=false;$('closeHowTo').focus()};$('closeHowTo').onclick=()=>{$('howToOverlay').hidden=true};$('howToOverlay').onclick=e=>{if(e.target===$('howToOverlay'))$('howToOverlay').hidden=true};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('detailOverlay').hidden=true;$('confirmOverlay').hidden=true;$('howToOverlay').hidden=true;detail=null}});$('guessSearch').oninput=renderSuggestions;$('guessSearch').onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){if(!filteredSuggestions.length)return;e.preventDefault();suggestionIndex=(suggestionIndex+(e.key==='ArrowDown'?1:-1)+filteredSuggestions.length)%filteredSuggestions.length;$$('.suggestion-item').forEach((b,i)=>b.setAttribute('aria-selected',i===suggestionIndex?'true':'false'));$$('.suggestion-item')[suggestionIndex]?.scrollIntoView({block:'nearest'})}if((e.key===' '||e.key==='Enter')&&filteredSuggestions.length){e.preventDefault();guess(filteredSuggestions[suggestionIndex].id)}};$('suggestions').onclick=e=>{let b=e.target.closest('[data-id]');if(b)guess(+b.dataset.id)};$$('[data-hint]').forEach(b=>b.onclick=()=>{activeHint=activeHint===b.dataset.hint?null:b.dataset.hint;renderHints()});init();
